script:
frappe.ui.form.on('QC Producto Muestra', {
    refresh: function(frm) {
        // Bloquear los botones de "Agregar Fila" y "Eliminar Fila"
        frm.set_df_property('detalle_resultados', 'cannot_add_rows', true);
        frm.set_df_property('detalle_resultados', 'cannot_delete_rows', true);
    },
    
    qc_producto: function(frm) {
        // Si el usuario cambia el producto antes de guardar, 
        // podrías disparar una llamada al servidor para refrescar la tabla
        if (frm.doc.qc_producto) {
            frm.trigger('cargar_desde_servidor');
        }
    }
});

frappe.ui.form.on('QC Muestra Detalle', {
    // 1. Lógica para parámetros NUMÉRICOS
    resultados: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.tipo_parametro === "Número") {
            let valor = flt(row.resultados);
            let min = flt(row.valor_minimo);
            let max = flt(row.valor_maximo);

            if (valor >= min && valor <= max) {
                row.indicador_vial = "🟢";
            } else {
                row.indicador_vial = "🔴";
            }
            frm.refresh_field("detalle_resultados");
        }
    },

    // 2. Lógica para parámetros de SELECCIÓN (Conforme / No Conforme)
    // Suponiendo que el campo se llama "conformidad"
    conformidad: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        
        if (row.tipo_parametro === "Selección") {
            if (row.conformidad === "Conforme") {
                row.indicador_vial = "🟢";
            } else if (row.conformidad === "No Conforme") {
                row.indicador_vial = "🔴";
            } else {
                row.indicador_vial = ""; // Limpiar si no hay selección
            }
            frm.refresh_field("detalle_resultados");
        }
    }
});
